import { useState } from 'react';
import {
  Alert, AlertActions, AlertBody, AlertTitle,
  Button, Card, Stat, StatLabel, StatNote, StatValue, Table, TableWrap, Tag, Td, Th,
} from '@gener8v/ui';

interface Region {
  id: string;
  name: string;
  /** USD millions. `null` means the system did not respond — which is not the same as zero. */
  revenue: number | null;
}

const INITIAL: Region[] = [
  { id: 'na', name: 'North America', revenue: 12.4 },
  { id: 'eu', name: 'Europe', revenue: 9.8 },
  { id: 'apac', name: 'Asia Pacific', revenue: 7.1 },
  { id: 'latam', name: 'Latin America', revenue: null },
  { id: 'mea', name: 'Middle East & Africa', revenue: null },
];

const usd = (m: number) => `$${m.toFixed(1)}M`;

const WarnIcon = () => (
  <svg viewBox="0 0 256 256" width="20" height="20" fill="currentColor" aria-hidden="true">
    <path d="M236.8,188.09,149.35,36.22h0a24.76,24.76,0,0,0-42.7,0L19.2,188.09a23.51,23.51,0,0,0,0,23.72A24.35,24.35,0,0,0,40.55,224h174.9a24.35,24.35,0,0,0,21.33-12.19A23.51,23.51,0,0,0,236.8,188.09ZM120,104a8,8,0,0,1,16,0v40a8,8,0,0,1-16,0Zm8,88a12,12,0,1,1,12-12A12,12,0,0,1,128,192Z" />
  </svg>
);

function list(names: string[]) {
  if (names.length <= 1) return names.join('');
  return `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`;
}

export function App() {
  const [regions, setRegions] = useState(INITIAL);
  const [retrying, setRetrying] = useState<Set<string>>(new Set());

  const received = regions.filter((r) => r.revenue !== null);
  const missing = regions.filter((r) => r.revenue === null);
  const partial = missing.length > 0;
  const sum = received.reduce((s, r) => s + (r.revenue ?? 0), 0);

  // Demo stand-in for re-querying the regional systems.
  function retry(ids: string[]) {
    setRetrying((p) => new Set([...p, ...ids]));
    window.setTimeout(() => {
      setRegions((rs) => rs.map((r) => (ids.includes(r.id) && r.revenue === null ? { ...r, revenue: 5.2 } : r)));
      setRetrying((p) => new Set([...p].filter((id) => !ids.includes(id))));
    }, 1200);
  }

  const missingIds = missing.map((r) => r.id);
  const retryingAny = missingIds.some((id) => retrying.has(id));

  return (
    <main className="container stack">
      <header>
        <h1>Revenue summary</h1>
        <p className="lede">Revenue across the five regional systems, as of today.</p>
      </header>

      {partial && (
        <Alert tone="warning" live icon={<WarnIcon />}>
          <AlertTitle>Incomplete: {received.length} of {regions.length} regions reported</AlertTitle>
          <AlertBody>
            {list(missing.map((r) => r.name))} did not respond. The figure below covers only the
            regions that did and is not the full revenue total.
          </AlertBody>
          <AlertActions>
            <Button variant="secondary" size="sm" loading={retryingAny} onClick={() => retry(missingIds)}>
              Retry {missing.length === 1 ? 'region' : `${missing.length} regions`}
            </Button>
          </AlertActions>
        </Alert>
      )}

      <Card className="card-pad-sm">
        <Stat>
          <StatLabel>
            {partial
              ? `Partial revenue · ${received.length} of ${regions.length} regions`
              : 'Total revenue · all regions'}
          </StatLabel>
          <StatValue>{usd(sum)}</StatValue>
          <StatNote>
            {partial ? (
              <>
                <Tag variant="warning">Partial</Tag>{' '}
                Excludes {list(missing.map((r) => r.name))}. Do not quote as the total.
              </>
            ) : (
              <Tag variant="success">Complete</Tag>
            )}
          </StatNote>
        </Stat>
      </Card>

      <TableWrap>
        <Table>
          <caption className="sr-only">Revenue by region</caption>
          <thead>
            <tr>
              <Th>Region</Th>
              <Th>Status</Th>
              <Th numeric>Revenue</Th>
              <Th><span className="sr-only">Action</span></Th>
            </tr>
          </thead>
          <tbody>
            {regions.map((r) => (
              <tr key={r.id}>
                <Td>{r.name}</Td>
                <Td>
                  {r.revenue === null
                    ? <Tag variant="warning">No response</Tag>
                    : <Tag variant="success">Received</Tag>}
                </Td>
                {r.revenue === null
                  ? <Td numeric className="muted">Not received</Td>
                  : <Td numeric>{usd(r.revenue)}</Td>}
                <Td>
                  {r.revenue === null && (
                    <Button variant="ghost" size="sm" loading={retrying.has(r.id)}
                      onClick={() => retry([r.id])} aria-label={`Retry ${r.name}`}>
                      Retry
                    </Button>
                  )}
                </Td>
              </tr>
            ))}
          </tbody>
        </Table>
      </TableWrap>
    </main>
  );
}
